{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 주차장 설치 및 관리 조례상 하루 주차권(1일주차권)에 경차 할인이 적용되는지 여부",
      "c_basis": "APPLIED",
      "d_claims": [
        {
          "a_text": "조례 제7조제1항제2호는 경형자동차(경차)에 대해 주차요금의 100분의 50을 할인할 수 있다고 정하고 있으며, 이 할인은 1일주차권을 포함한 주차요금에 적용된다. 다만 1일주차권 자체가 경차 할인 대상에서 제외된다는 별도 규정은 원문에 없다. 따라서 경차라면 1일주차권에도 100분의 50 할인이 적용될 수 있다.",
          "b_ids": "주차장:제7조제1항제2호"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
